      padding: 12px 14px;
      color: var(--muted);
      font-size: 0.95rem;
      min-width: 150px;
    }

    .figure {
      margin: 24px 0 20px;
      border-radius: 24px;
      overflow: hidden;
      position: relative;
      background: #dfe8fb;
      border: 1px solid rgba(109, 125, 156, 0.18);
      aspect-ratio: 4 / 3;
    }

    .figure img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .figure-badge {
      position: absolute;
      top: 18px;
      left: 18px;
      padding: 10px 14px;
      border-radius: 999px;
      background: rgba(17, 24, 39, 0.7);
      color: #fff;
      font-size: 0.88rem;
      font-weight: 600;
      backdrop-filter: blur(12px);
    }

    .actions {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
