    .modal-icon {
      width: 52px;
      height: 52px;
      border-radius: 18px;
      display: grid;
      place-items: center;
      background: rgba(229, 72, 77, 0.12);
      color: var(--danger);
      font-size: 1.4rem;
      margin-bottom: 18px;
